// 🧠 Improved Freshness Filter for Football News
const items = $input.all();
const now = new Date();
const cutoffHours = 8; // Keep only articles within the last 8 hours
const freshStories = [];
const skippedStories = [];
const sourceCount = {}; // For debug summary

for (const item of items) {
  const json = item.json;

  // Try multiple possible date fields
  const possibleDates = [
    json.pubDate,
    json.isoDate,
    json.date,
    json.updated,
    json.created,
  ].filter(Boolean);

  // Parse the first valid date
  let pubDate = null;
  for (const d of possibleDates) {
    const parsed = new Date(d);
    if (!isNaN(parsed.getTime())) {
      pubDate = parsed;
      break;
    }
  }

  // Calculate age if valid
  let isFresh = false;
  if (pubDate) {
    const ageHours = (now - pubDate) / (1000 * 60 * 60);
    isFresh = ageHours <= cutoffHours;

    // Debug: Log articles being filtered out
    if (!isFresh) {
      console.log(`⏰ TOO OLD (${Math.round(ageHours)}h ago): ${json.title}`);
      skippedStories.push({
        title: json.title,
        ageHours: Math.round(ageHours * 10) / 10
      });
    }
  } else {
    // If date missing or invalid, SKIP IT for safety
    isFresh = false;  // ← FIXED!
    console.log(`⚠️ NO VALID DATE - SKIPPING: ${json.title}`);
    skippedStories.push({
      title: json.title,
      reason: "No valid date"
    });
  }

  if (isFresh) {
    freshStories.push(item);
    const src = json.source || json.link?.split("/")[2] || "Unknown Source";
    sourceCount[src] = (sourceCount[src] || 0) + 1;
  }
}

// 🧾 Debug summary
console.log("✅ KEPT:", freshStories.length, "fresh items");
console.log("❌ SKIPPED:", skippedStories.length, "old/undated items");
console.log("📊 Fresh stories by source:", sourceCount);
console.log("🗑️ Skipped stories:", skippedStories.slice(0, 5)); // Show first 5 skipped

return freshStories;

/**
 * Smart Football Deduplication Node for n8n
 * ------------------------------------------------------------
 * ✅ Removes duplicate football stories across RSS feeds
 * ✅ Normalizes club aliases
 * ✅ Detects player names BEFORE lowercase normalization
 * ✅ Keeps different stories involving the same player/club
 * ✅ Detects football relevance safely
 * ✅ JavaScript-compatible regex
 */

const items = $input.all();


// ============================================================
// 1. CLUB ALIAS NORMALIZATION MAP
// ============================================================

const clubMap = {
  "man city": "Manchester City",
  "manchester city fc": "Manchester City",
  "citizens": "Manchester City",
  "mcfc": "Manchester City",

  "man united": "Manchester United",
  "manchester united fc": "Manchester United",
  "red devils": "Manchester United",
  "mufc": "Manchester United",

  "arsenal fc": "Arsenal",
  "gunners": "Arsenal",

  "chelsea fc": "Chelsea",
  "the blues": "Chelsea",

  "liverpool fc": "Liverpool",
  "liverpool fc.": "Liverpool",
  "reds": "Liverpool",

  "psg": "Paris Saint-Germain",
  "paris saint germain": "Paris Saint-Germain",
  "paris sg": "Paris Saint-Germain",

  "real madrid cf": "Real Madrid",
  "los blancos": "Real Madrid",

  "barca": "Barcelona",
  "fc barcelona": "Barcelona",
  "blaugrana": "Barcelona",

  "juve": "Juventus",
  "juventus fc": "Juventus",
  "old lady": "Juventus",

  "bayern": "Bayern Munich",
  "bayern münchen": "Bayern Munich",
  "fc bayern": "Bayern Munich",

  "inter": "Inter Milan",
  "internazionale": "Inter Milan",

  "acm": "AC Milan",

  "atleti": "Atletico Madrid",
  "atlético": "Atletico Madrid",
  "colchoneros": "Atletico Madrid",

  "roma": "AS Roma",
  "napoli": "Napoli",

  "borussia dortmund": "Dortmund",
  "bvb": "Dortmund"
};


// ============================================================
// 2. PLAYER DETECTION
// IMPORTANT:
// Detect names BEFORE lowercase normalization.
// ============================================================

function detectPlayers(text) {

  if (!text) return [];

  const matches = text.match(
    /\b[A-ZÀ-ÖØ-Þ][a-zà-öø-ÿ'-]+(?:\s+[A-ZÀ-ÖØ-Þ][a-zà-öø-ÿ'-]+){1,2}\b/g
  ) || [];

  return [...new Set(
    matches.map(name =>
      name
        .toLowerCase()
        .replace(/[^\p{L}\s'-]/gu, "")
        .replace(/\s+/g, " ")
        .trim()
    )
  )];
}


// ============================================================
// 3. NORMALIZE CLUBS
// ============================================================

function normalizeClubs(text) {

  let normalized = String(text || "").toLowerCase();

  // Replace longer aliases first
  const aliases = Object.keys(clubMap)
    .sort((a, b) => b.length - a.length);

  for (const alias of aliases) {

    const escapedAlias = alias.replace(
      /[.*+?^${}()|[\]\\]/g,
      "\\$&"
    );

    const regex = new RegExp(
      `\\b${escapedAlias}\\b`,
      "gi"
    );

    normalized = normalized.replace(
      regex,
      clubMap[alias].toLowerCase()
    );
  }

  return normalized;
}


// ============================================================
// 4. TEXT NORMALIZATION
// ============================================================

function normalizeText(text) {

  return String(text || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}


// ============================================================
// 5. KNOWN CLUBS
// ============================================================

const clubs = [
  ...new Set(
    Object.values(clubMap).map(club =>
      normalizeText(club)
    )
  )
];


// ============================================================
// 6. FOOTBALL KEYWORDS
// ============================================================

const footballKeywords = [
  "goal",
  "match",
  "transfer",
  "league",
  "cup",
  "football",
  "manager",
  "coach",
  "player",
  "signs",
  "signed",
  "contract",
  "injury",
  "injured",
  "deal",
  "agrees",
  "agreement",
  "bid",
  "talks",
  "negotiation",
  "premier league",
  "champions league",
  "europa league",
  "conference league",
  "world cup",
  "qualifier",
  "qualifiers",
  "fixture",
  "fixtures",
  "squad",
  "lineup",
  "line-up",
  "starting xi",
  "penalty",
  "red card",
  "yellow card",
  "manager",
  "managerial",
  "midfielder",
  "defender",
  "striker",
  "goalkeeper",
  "forward"
];


// ============================================================
// 7. FOOTBALL RELEVANCE CHECK
// ============================================================

function containsFootballKeyword(text) {

  const normalized = normalizeText(text);

  return footballKeywords.some(keyword => {

    const normalizedKeyword = normalizeText(keyword);

    return normalized.includes(normalizedKeyword);
  });
}


// ============================================================
// 8. DEDUPLICATION
// ============================================================

const seen = new Set();
const uniqueItems = [];

for (const item of items) {

  const title =
    item.json.title ||
    item.json.Title ||
    item.json.headline ||
    "";

  const description =
    item.json.description ||
    item.json.content ||
    item.json.contentSnippet ||
    "";

  if (!title) {

    console.log("🚫 Skipping article with no title");

    continue;
  }


  // ----------------------------------------------------------
  // Detect players BEFORE normalization
  // ----------------------------------------------------------

  const originalText = `${title} ${description}`;

  const foundPlayers = detectPlayers(originalText);


  // ----------------------------------------------------------
  // Normalize club aliases
  // ----------------------------------------------------------

  const combined = normalizeClubs(originalText);


  // ----------------------------------------------------------
  // Detect canonical clubs
  // ----------------------------------------------------------

  const foundClubs = clubs.filter(club =>
    combined.includes(club)
  );


  // ----------------------------------------------------------
  // Normalize title
  // ----------------------------------------------------------

  const titlePart = normalizeText(title)
    .slice(0, 100);


  // ----------------------------------------------------------
  // Football relevance
  // ----------------------------------------------------------

  const isFootballStory =
    containsFootballKeyword(combined);


  // ----------------------------------------------------------
  // Build deduplication key
  // ----------------------------------------------------------

  const key =
    `${foundPlayers.sort().join(",")}|` +
    `${foundClubs.sort().join(",")}|` +
    `${titlePart}`;


  // ----------------------------------------------------------
  // Keep relevant unique stories
  // ----------------------------------------------------------

  if (
    !seen.has(key) &&
    (
      foundClubs.length > 0 ||
      foundPlayers.length > 0 ||
      isFootballStory
    )
  ) {

    seen.add(key);

    uniqueItems.push(item);

    console.log(`✅ KEEP: ${title}`);
    console.log(
      `   👤 Players: ${foundPlayers.join(", ") || "None"}`
    );
    console.log(
      `   ⚽ Clubs: ${foundClubs.join(", ") || "None"}`
    );

  } else {

    console.log(`🚫 DUPLICATE / IRRELEVANT: ${title}`);
    console.log(`   🔑 Key: ${key}`);

  }
}


// ============================================================
// 9. DEBUG SUMMARY
// ============================================================

console.log("==========================================");
console.log("⚽ SMART FOOTBALL DEDUPLICATOR");
console.log("==========================================");
console.log(`📥 Input: ${items.length}`);
console.log(`✅ Kept: ${uniqueItems.length}`);
console.log(`🚫 Removed: ${items.length - uniqueItems.length}`);
console.log("==========================================");


return uniqueItems;

return items.map(item => {
  const html = item.json.data || item.json.body || '';

  // 1. OpenGraph image (primary)
  const ogMatch = html.match(/<meta property="og:image" content="([^"]+)"/i);
  const ogImage = ogMatch ? ogMatch[1] : null;

  // 2. OpenGraph video image (fallback for video posts)
  const videoMatch = html.match(/<meta property="og:video:image" content="([^"]+)"/i);
  const videoImage = videoMatch ? videoMatch[1] : null;

  // 3. Generic fallback (sometimes ESPN embeds thumbnails in img tags)
  const imgMatch = html.match(/<img[^>]+src="([^"]+(?:jpg|jpeg|png))"/i);
  const imgFallback = imgMatch ? imgMatch[1] : null;

  // Final priority chain
  const imageUrl = ogImage || videoImage || imgFallback || null;

  return {
    json: {
      imageUrl
    }
  };
});

return items.map(item => {
  const html = item.json.data || item.json.body || '';

  // Try to extract the first image in the article HTML
  const imageMatch = html.match(/<img[^>]+src="([^">]+)"/i);
  const imageUrl = imageMatch ? imageMatch[1] : null;

  // Return ONLY the image — let Merge combine it with RSS
  return {
    json: {
      imageUrl
    }
  };
});

// 🧹 Strict BBC-Style Standardizer
return items.map(item => {
  const d = item.json;

  // 1. Locate the raw text
  let rawContent = d['content:encoded'] || d.content || d.description || "";

  // 2. 🖼️ IMAGE HUNTER: Find the image and save it
  let extractedImage = d.imageUrl || ""; 

  if (!extractedImage && d.enclosure && d.enclosure.url) {
    extractedImage = d.enclosure.url; 
  } else if (!extractedImage && Array.isArray(d.enclosures) && d.enclosures.length > 0) {
    extractedImage = d.enclosures[0].url;
  } else if (!extractedImage && rawContent) {
    const imgMatch = rawContent.match(/<img[^>]+src=["']([^"']+)["']/i);
    if (imgMatch) {
        extractedImage = imgMatch[1];
    }
  }

  // Fix annoying double-slash URLs
  if (extractedImage && extractedImage.startsWith('//')) {
      extractedImage = 'https:' + extractedImage;
  }

  // 3. 🧼 HTML STRIPPER: Wash the code out to create pure text
  let cleanText = rawContent
    .replace(/<[^>]*>?/gm, ' ') // Rips out all HTML tags
    .replace(/&#8216;/g, "'").replace(/&#8217;/g, "'") 
    .replace(/&#8220;/g, '"').replace(/&#8221;/g, '"')
    .replace(/&#8230;/g, '...') 
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ').trim(); 

  // 4. Fallback generators for missing data
  let snippet = d.contentSnippet || d.description || cleanText.substring(0, 150) + "...";
  let pubDate = d.pubDate || new Date().toUTCString();
  let isoDate = d.isoDate || new Date(pubDate).toISOString();
  let guid = d.guid || d.id || d.link || "";

  // 5. 📦 STRICT OUTPUT: Only output the exact 8 fields BBC uses
  return {
    json: {
      title: d.title || "No Title",
      link: d.link || "",
      pubDate: pubDate,
      content: cleanText,
      contentSnippet: snippet,
      guid: guid,
      isoDate: isoDate,
      imageUrl: extractedImage
    }
  };
});

const items = $input.all();
const staticData = $getWorkflowStaticData('global');

if (!staticData.postedStories) {
  staticData.postedStories = [];
}

const output = [];

// Normalize text consistently
function normalize(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/[^\w\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

for (const item of items) {
  const data = item.json || {};

  // -----------------------------------------
  // 1. GET TITLE
  // -----------------------------------------
  const title =
    data.title ||
    data.Title ||
    data.headline ||
    '';

  // -----------------------------------------
  // 2. GET URL
  // -----------------------------------------
  const url =
    data.url ||
    data.link ||
    '';

  // -----------------------------------------
  // 3. GET IMAGE
  // -----------------------------------------
  const image =
    data.imageUrl ||
    data.image ||
    data.image_url ||
    data.media?.url ||
    data.enclosure?.url ||
    '';

  // -----------------------------------------
  // 4. CLEAN VALUES
  // -----------------------------------------
  const cleanTitle = String(title).trim();
  const cleanUrl = String(url).trim();
  const cleanImage = String(image).trim();

  // -----------------------------------------
  // 5. NO IMAGE = SKIP
  // -----------------------------------------
  if (!cleanImage) {
    console.log(`🚫 SKIPPED — No image: ${cleanTitle}`);
    continue;
  }

  // -----------------------------------------
  // 6. INVALID ARTICLE = SKIP
  // -----------------------------------------
  if (!cleanTitle || !cleanUrl) {
    console.log(`🚫 SKIPPED — Missing title or URL`);
    continue;
  }

  // -----------------------------------------
  // 7. GENERATE STORY ID
  // -----------------------------------------
  const storyId = normalize(`${cleanTitle}|${cleanUrl}`);

  // -----------------------------------------
  // 8. CHECK PREVIOUSLY POSTED STORIES
  // -----------------------------------------
  if (staticData.postedStories.includes(storyId)) {
    console.log(`🚫 DUPLICATE — Already posted: ${cleanTitle}`);
    continue;
  }

  // -----------------------------------------
  // 9. PASS NEW STORY
  // -----------------------------------------
  output.push({
    json: {
      ...data,
      imageUrl: cleanImage,
      storyId
    }
  });

  console.log(`✅ NEW STORY: ${cleanTitle}`);
}

console.log(`📊 Input stories: ${items.length}`);
console.log(`📤 Stories passed forward: ${output.length}`);

return output;

const items = $input.all();
const staticData = $getWorkflowStaticData('global');

// Initialize persistent storage
if (!Array.isArray(staticData.postedStories)) {
  staticData.postedStories = [];
}

for (const item of items) {

  const data = item.json || {};

  // ============================================================
  // 1. STORY ID
  // ============================================================

  const storyId = String(
    data.storyId ||
    data.story_id ||
    ''
  ).trim();

  if (!storyId) {
    console.log('🚫 Successful Post Logger: Missing storyId');
    continue;
  }


  // ============================================================
  // 2. ONLY ACCEPT CONFIRMED SUCCESS
  // ============================================================

  if (data.error) {
    console.log(`❌ Post failed — NOT logging: ${storyId}`);
    continue;
  }

  if (data.postSuccess !== true) {
    console.log(
      `❌ Post not confirmed successful — NOT logging: ${storyId}`
    );
    continue;
  }


  // ============================================================
  // 3. PLATFORM
  // ============================================================

  const platform =
    String(data.platform || 'unknown').toLowerCase();


  // ============================================================
  // 4. CHECK IF STORY ALREADY EXISTS
  // ============================================================

  const existingStory = staticData.postedStories.find(
    story => story.storyId === storyId
  );


  // ============================================================
  // 5. STORY ALREADY LOGGED
  // ============================================================

  if (existingStory) {

    // Add platform if it is new
    if (
      platform !== 'unknown' &&
      !existingStory.platforms.includes(platform)
    ) {
      existingStory.platforms.push(platform);
    }

    // Save Facebook post ID
    if (
      platform === 'facebook' &&
      data.facebookPostId
    ) {
      existingStory.facebookPostId =
        data.facebookPostId;
    }

    // Save X response
    if (
      platform === 'x' &&
      data.xResponse
    ) {
      existingStory.xResponse =
        data.xResponse;
    }

    console.log(
      `⚠️ Story already logged: ${storyId} (${platform})`
    );

    continue;
  }


  // ============================================================
  // 6. CREATE SUCCESSFUL STORY RECORD
  // ============================================================

  staticData.postedStories.push({

    storyId,

    url:
      data.url ||
      data.link ||
      '',

    platforms:
      platform !== 'unknown'
        ? [platform]
        : [],

    facebookPostId:
      platform === 'facebook'
        ? data.facebookPostId || ''
        : '',

    xResponse:
      platform === 'x'
        ? data.xResponse || ''
        : '',

    loggedAt:
      new Date().toISOString()
  });


  console.log(
    `✅ Successfully logged story: ${storyId} (${platform})`
  );
}


// ============================================================
// 7. KEEP MEMORY UNDER CONTROL
// ============================================================

const MAX_STORIES = 100;

if (staticData.postedStories.length > MAX_STORIES) {
  staticData.postedStories =
    staticData.postedStories.slice(-MAX_STORIES);
}


// ============================================================
// 8. DEBUG
// ============================================================

console.log(
  `📊 Successful stories stored: ${staticData.postedStories.length}`
);

return items;

const items = $input.all();

const bannedKeywords = [
  "betting",
  "odds",
  "bookmakers",
  "prediction",
  "predictions",
  "tips",
  "accumulator",
  "parlay",
  "fantasy football",
  "opinion",
  "opinion:",
  "rumour rating",
  "transfer rumours live",
  "live blog",
  "watch live",
  "stream",
  "how to watch"
];

function isBadContent(text) {
  text = (text || "").toLowerCase();
  return bannedKeywords.some(word => text.includes(word));
}

return items.filter(item => {
  const title = item.json.title || item.json.Title || "";
  const desc = item.json.content || item.json.description || "";

  const combined = `${title} ${desc}`;

  const bad = isBadContent(combined);

  if (bad) {
    console.log("🚫 Filtered out:", title);
    return false;
  }

  return true;
});

const items = $input.all();

function normalize(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function storyKey(title, url) {
  const normalizedTitle = normalize(title);
  const normalizedUrl = normalize(url);

  return `${normalizedTitle} | ${normalizedUrl}`;
}

return items.map(item => {

  const title =
    item.json.Title ||
    item.json.title ||
    item.json.headline ||
    '';

  const url =
    item.json.url ||
    item.json.link ||
    '';

  // Safety: a story needs at least a title or URL
  if (!title && !url) {
    item.json.storyId = '';
    return item;
  }

  item.json.storyId = storyKey(title, url);

  return item;
});

